// Package semconv lists the OpenTelemetry attribute keys that batch format 5
// stores in dedicated columns. keys_gen.go is generated by
// internal/cmd/semconvgen from the pinned semantic conventions release
// (`just semconv-generate`); a changed list needs a new batch format.
package semconv

// Scope says whether a key is a span attribute or a resource attribute.
type Scope uint8

const (
	Span Scope = iota
	Resource
)

// Type is the semconv value type; a column holds values converted to it.
type Type uint8

const (
	String Type = iota
	Int
)

// Key is one dedicated column. Bit is the key's position in Keys, which
// indexes per-key spill counts; Source is the semconv group that selected it.
type Key struct {
	Name   string
	Scope  Scope
	Type   Type
	Column string
	Bit    uint8
	Source string
}

type ref struct {
	scope Scope
	name  string
}

var index = func() map[ref]int {
	m := make(map[ref]int, len(Keys))
	for i, k := range Keys {
		m[ref{k.Scope, k.Name}] = i
	}
	return m
}()

// Lookup returns the key with this exact name in scope.
func Lookup(scope Scope, name string) (Key, bool) {
	i, ok := index[ref{scope, name}]
	if !ok {
		return Key{}, false
	}
	return Keys[i], true
}
